        ["MarineText"] = ("Coordinated Dive Hub’s participation in the EU-funded bicommunal project. Delivered Discover Scuba Diving programs for high school students, organized beach and underwater cleanups, and collaborated with international stakeholders on marine conservation and sustainability.", "AB tarafından finanse edilen iki toplumlu projede Dive Hub’ın katılımını koordine ettim. Lise öğrencilerine Discover Scuba Diving programları sundum; kıyı ve sualtı temizlikleri düzenledim. Denizlerin korunması ve sürdürülebilirlik çalışmalarında uluslararası paydaşlarla iş birliği yaptım."),
        ["DivemasterRoleMeta"] = ("Dive Hub · Trikomo, TRNC · May 2013–Oct 2014", "Dive Hub · İskele, KKTC · Mayıs 2013–Ekim 2014"),
        ["DivemasterRole"] = ("Divemaster", "Divemaster"),
        ["DivemasterText"] = ("Assisted instructors with training and student management; guided certified divers, demonstrated diving skills, assessed students and supported equipment preparation, maintenance, rentals and tank filling.", "Eğitim ve öğrenci takibinde eğitmenlere destek verdim. Sertifikalı dalıcılara rehberlik ettim, dalış becerilerini göstererek öğrencileri değerlendirdim. Ekipman hazırlığı, bakım, kiralama ve tüp dolumunda görev aldım."),
        ["HalkbankRoleMeta"] = ("Türkiye Halkbankası A.Ş. · Headquarters, Istanbul · Jun–Sep 2011", "Türkiye Halkbankası A.Ş. · Genel Müdürlük, İstanbul · Haziran–Eylül 2011"),
        ["HalkbankRole"] = ("Software Developer Intern", "Yazılım Geliştirme Stajyeri"),
        ["HalkbankText"] = ("Worked with the software development team to build PL/SQL reporting programs on IBM DB2 databases, generating bill payment and corporate revenue reports for bank branches nationwide and providing software support.", "Yazılım geliştirme ekibiyle IBM DB2 veritabanları üzerinde PL/SQL raporlama programları geliştirdim. Türkiye genelindeki banka şubeleri için fatura ödeme ve kurumsal gelir raporları hazırladım; yazılım desteği sağladım."),
        ["AiesecITRoleMeta"] = ("AIESEC Eastern Mediterranean · Sep–Nov 2009", "AIESEC Doğu Akdeniz · Eylül–Kasım 2009"),
        ["AiesecITRole"] = ("IT Project Team Leader", "BT Proje Ekip Lideri"),
        ["AiesecITText"] = ("Led an international internship team developing a web-based student portal for Eastern Mediterranean University. Managed the project lifecycle and cross-cultural collaboration, and presented results at the Local Congress.", "Doğu Akdeniz Üniversitesi için web tabanlı öğrenci portalı geliştiren uluslararası staj ekibine liderlik ettim. Proje yaşam döngüsünü yönettim ve farklı kültürlerden ekip üyeleri arasındaki iş birliğini koordine ettim. Çalışmanın sonuçlarını Yerel Kongre’de sundum."),
        ["AiesecEventRoleMeta"] = ("AIESEC Eastern Mediterranean · ATCOM’09 · May–Sep 2009", "AIESEC Doğu Akdeniz · ATCOM’09 · Mayıs–Eylül 2009"),
        ["AiesecEventRole"] = ("Organization Committee Member", "Organizasyon Komitesi Üyesi"),
        ["AiesecEventText"] = ("Helped organize a national congress for 170 delegates, coordinating sponsorships, budgets, contracts, suppliers, accommodation, transport, catering, delegate packs and social events.", "170 delegenin katıldığı ulusal kongrenin organizasyonunda görev aldım. Sponsorluk, bütçe, sözleşme ve tedarikçi süreçlerinin yanı sıra konaklama, ulaşım, ikram, delege paketleri ve sosyal etkinliklerin hazırlanmasına katkı sağladım."),
        ["HotelRoleMeta"] = ("Mount Olympus Water & Theme Park, Hotel Rome · Wisconsin, USA · 2008", "Mount Olympus Water & Theme Park, Hotel Rome · Wisconsin, ABD · 2008"),
        ["HotelRole"] = ("Housekeeper", "Kat Görevlisi"),
        ["HotelText"] = ("Maintained guest rooms and public areas, monitored inventory and responded to guest requests as part of the operations team.", "Misafir odalarının ve ortak alanların temizlik ve düzenini sağladım. Envanteri takip ettim ve operasyon ekibiyle birlikte misafir taleplerini karşıladım."),
        ["McDonaldsRoleMeta"] = ("McDonald’s · Wisconsin, USA · Jun–Jul 2008", "McDonald’s · Wisconsin, ABD · Haziran–Temmuz 2008"),
        ["McDonaldsRole"] = ("Crew Member", "Ekip Üyesi"),
        ["McDonaldsText"] = ("Supported customer service, food preparation, daily operations and cleanliness; assisted with onboarding and training new employees.", "Müşteri hizmetleri, yemek hazırlığı, günlük operasyonlar ve temizlik işlerinde görev aldım. Yeni çalışanların işe uyumuna ve eğitimine destek verdim."),
