        ["MarineResearch"] = ("Marine Litter: Together for Clean Coasts!", "Marine Litter: Together for Clean Coasts!"),
        ["MarineResearchText"] = ("EU Aid Programme for the Turkish Cypriot Community · Sep 2016–Jun 2021. Dive Hub representative, diving instructor and captain; marine litter awareness, coastal and underwater cleanups, youth environmental education and sustainable marine practices.", "Kıbrıs Türk Toplumuna Yönelik AB Yardım Programı · Eylül 2016–Haziran 2021. Dive Hub temsilcisi, dalış eğitmeni ve kaptan olarak denizel atık farkındalığı, kıyı ve sualtı temizliği, gençlere yönelik çevre eğitimi ve sürdürülebilir denizcilik çalışmalarında görev aldım."),
        ["MonitoringResearch"] = ("Marine litter monitoring · Cyprus, 2021", "Denizel atık izleme · Kıbrıs, 2021"),
        ["MonitoringResearchText"] = ("Contributed to marine litter monitoring, data collection, coastal observations and field operations. Acknowledged as a contributing team member in Orthodoxou et al. (2022), “Seasonal and geographic variations of marine litter: A comprehensive study from the island of Cyprus,” Marine Pollution Bulletin, 177, 113495.", "Denizel atık izleme, veri toplama, kıyı gözlemleri ve saha çalışmalarına katkıda bulundum. Orthodoxou ve diğerlerinin (2022) “Seasonal and geographic variations of marine litter: A comprehensive study from the island of Cyprus,” başlıklı makalesinin teşekkür bölümünde katkı sağlayan ekip üyesi olarak yer aldım (Marine Pollution Bulletin, 177, 113495)."),
        ["UnderwaterResearch"] = ("Scientific underwater research · May 2018", "Bilimsel sualtı araştırmaları · Mayıs 2018"),
        ["UnderwaterResearchText"] = ("Captain, logistics coordinator and diving instructor for Cyprus International University’s Archaeology, Cultural Heritage and Conservation Center; supported underwater archaeology and cultural heritage research operations.", "Uluslararası Kıbrıs Üniversitesi Arkeoloji, Kültürel Miras ve Koruma Merkezi’nin sualtı arkeolojisi ve kültürel miras araştırmalarına operasyonel destek sağladım. Kaptan, lojistik koordinatörü ve dalış eğitmeni olarak görev aldım."),
