        ["TourismResearchText"] = ("Sustainable tourism, scuba diving tourism, marine tourism and sustainable consumer behaviour.", "Sürdürülebilir turizm, tüplü dalış turizmi, deniz turizmi ve sürdürülebilir tüketici davranışı."),
