        ["ContactDetailsHeading"] = ("Contact details", "İletişim bilgileri"),
        ["ExperienceIntro"] = ("Experience across software, technical operations, diving, business management and international projects.", "Yazılım geliştirme, teknik operasyonlar ve işletme yönetimi alanlarında çalıştım. Mesleki geçmişim dalış eğitimi, uluslararası projeler ve gönüllü çalışmaları da kapsıyor."),
        ["ResearchIntro"] = ("My academic work brings information technology together with sustainable diving tourism and environmental stewardship.", "Mobil uygulamaların sürdürülebilir dalış turizmine ve çevresel sorumluluğa katkısını araştırıyorum. Akademik yayınlarım ve saha çalışmalarım bilgi teknolojileri ile turizm işletmeciliğini bir araya getiriyor."),
        ["CreativeIntro"] = ("Underwater video, graphic design and digital content informed by hands-on experience in diving tourism.", "Dalış turizmindeki saha deneyimime dayanan sualtı videoları, grafik tasarımlar ve dijital içerikler."),
        ["AwardsIntro"] = ("Four second-place awards in underwater nature and archaeology video competitions, alongside professional diving and maritime qualifications.", "Uluslararası sualtı doğa ve arkeoloji video yarışmalarında kazandığım dört ikincilik ödülü ile dalış ve denizcilik alanındaki mesleki belgelerim."),
        ["ContactIntro"] = ("For software, research or creative collaborations, get in touch by email.", "Yazılım geliştirme, araştırma ve yaratıcı projelerde iş birliği için e-posta ile bana ulaşabilirsiniz."),

