        ["ReadPublication"] = ("Read the publication", "Yayını incele"),
        ["UniversityRecord"] = ("View the article in the university repository", "Üniversite arşivinde incele"),
        ["VisitDiveHub"] = ("Discover Dive Hub", "Dive Hub web sitesini incele"),
        ["SocialProfiles"] = ("Social and portfolio profiles", "Sosyal medya ve portfolyo profilleri")
    };

    public string Translate(string key)
    {
        if (!_translations.TryGetValue(key, out var translation))
            return key;

        return CurrentLanguage == "tr" ? translation.Tr : translation.En;
    }

    public void SetLanguage(string language)
    {
        if (language != "en" && language != "tr")
            return;

        if (CurrentLanguage == language)
            return;

        CurrentLanguage = language;
        LanguageChanged?.Invoke();
    }
}
